export function parsePayment(payment, expectedCurrency) {
  const amount = payment?.amount;
  if (!payment || typeof payment !== 'object' || Array.isArray(payment)
    || typeof payment.id !== 'string' || payment.id.length === 0
    || !['EUR', 'USD'].includes(expectedCurrency)
    || !amount || typeof amount !== 'object' || Array.isArray(amount)
    || amount.currency_code !== expectedCurrency || typeof amount.value !== 'string'
    || amount.value.length > 32 || !/^(?:0|[1-9][0-9]*)\.[0-9]{2}$/u.test(amount.value)) {
    throw new Error('Invalid payment response.');
  }
  // The fictional EUR/USD contract explicitly defines two decimal places; no floating-point rounding is permitted.
  const amountMinor = BigInt(amount.value.replace('.', ''));
  if (amountMinor > BigInt(Number.MAX_SAFE_INTEGER)) throw new Error('Invalid payment response.');
  return { reference: payment.id, amountMinor: Number(amountMinor), currency: amount.currency_code };
}
